spawn.example:
const pile = kcds.world.StonePile.spawn(new kcds.math.Vector3(100, 200, 22));
pile.stones = 20;
pile.damage = 80;

kcds.core.Events.on('stoneImpact', (source, where, thrower) => {
  console.log(`player ${thrower.id} dropped a stone at ${where}`);
});

spawn.exampleCs:
var pile = StonePile.Spawn(new Vector3(100, 200, 22));
pile.Stones = 20;
pile.Damage = 80;

Events.On("stoneImpact", (JsValue source, Vector3 where, Player thrower) =>
{
    Log.Info($"player {thrower.Id} dropped a stone at {where}");
});
